/* Physical memory manager and slab for the operator-authored R1 fallback tree.
 *
 * NOT generated by the local model. Written by the campaign operator (Claude Code) from
 * agent/kernel_spec/subsystems/mm.md so that R2 and later runs, which build on a working memory
 * manager, can run after R1 failed. See docs/campaign/runs.yaml (r1-mm fallback).
 *
 * Portable: memory it hands out is touched only through phys_to_virt(), a panic halts through
 * arch_halt(), and the kernel image is read from the linker symbols. */
#include <stdint.h>
#include <stddef.h>
#include "mm.h"
#include "kernel.h"
#include "hal.h"

extern char __kernel_start[], __kernel_end[];

#define LOW_MEMORY_END 0x100000ULL          /* the first MiB: BIOS, VGA, boot structures */

static uint8_t *bitmap;                     /* 1 bit per frame: set = reserved or in use */
static uint64_t total_frames, reserved_frames, used_frames;

static int  test_bit(uint64_t f) { return bitmap[f >> 3] & (1u << (f & 7)); }
static void set_bit(uint64_t f)  { bitmap[f >> 3] |= (uint8_t)(1u << (f & 7)); }
static void clr_bit(uint64_t f)  { bitmap[f >> 3] &= (uint8_t)~(1u << (f & 7)); }

static uint64_t down(uint64_t a) { return a / PAGE_SIZE * PAGE_SIZE; }
static uint64_t up(uint64_t a)   { return (a + PAGE_SIZE - 1) / PAGE_SIZE * PAGE_SIZE; }

/* Reserve whole frames, start rounded down and end rounded up. */
static void reserve(uint64_t start, uint64_t size)
{
	uint64_t first = start / PAGE_SIZE;
	uint64_t last = (start + size + PAGE_SIZE - 1) / PAGE_SIZE;
	for (uint64_t f = first; f < last && f < total_frames; f++)
		if (!test_bit(f)) { set_bit(f); reserved_frames++; }
}

static void panic(const char *what, void *addr)
{
	kprintf("PANIC: %s (%p)\n", what, addr);
	arch_halt();
	for (;;) { }                            /* arch_halt may return (a host's does not) */
}

/* The lowest address above the kernel image where `bytes` fit in available RAM. */
static uint64_t place_bitmap(const boot_mmap_t *mmap, uint64_t bytes)
{
	uint64_t ks = (uint64_t)(uintptr_t)__kernel_start, ke = (uint64_t)(uintptr_t)__kernel_end;
	uint64_t best = 0;
	for (uint32_t i = 0; i < mmap->count; i++) {
		const boot_mmap_entry_t *e = &mmap->entries[i];
		if (e->type != 1)
			continue;
		uint64_t base = up(e->base_addr < LOW_MEMORY_END ? LOW_MEMORY_END : e->base_addr);
		if (base < up(ke) && base + bytes > ks)
			base = up(ke);                  /* not on top of the kernel image */
		if (base + bytes <= e->base_addr + e->length && (!best || base < best))
			best = base;
	}
	return best;
}

void pmm_init(const boot_mmap_t *mmap)
{
	uint64_t highest = 0;
	for (uint32_t i = 0; i < mmap->count; i++) {
		const boot_mmap_entry_t *e = &mmap->entries[i];
		if (e->type == 1 && e->base_addr + e->length > highest)
			highest = e->base_addr + e->length;
	}
	total_frames = highest / PAGE_SIZE;
	reserved_frames = used_frames = 0;

	uint64_t bytes = (total_frames + 7) / 8;
	uint64_t where = place_bitmap(mmap, bytes);
	if (!where)
		panic("pmm_init: no available region holds the frame bitmap", NULL);
	bitmap = phys_to_virt(where);

	/* Everything reserved, then each available region's whole frames freed, then anything the
	 * map calls reserved (type != 1) reserved again: a region the firmware claims wins. */
	kmemset(bitmap, 0xFF, bytes);
	reserved_frames = total_frames;
	for (uint32_t i = 0; i < mmap->count; i++) {
		const boot_mmap_entry_t *e = &mmap->entries[i];
		if (e->type != 1)
			continue;
		for (uint64_t f = up(e->base_addr) / PAGE_SIZE;
		     (f + 1) * PAGE_SIZE <= e->base_addr + e->length && f < total_frames; f++)
			if (test_bit(f)) { clr_bit(f); reserved_frames--; }
	}
	for (uint32_t i = 0; i < mmap->count; i++) {
		const boot_mmap_entry_t *e = &mmap->entries[i];
		if (e->type != 1)
			reserve(down(e->base_addr), up(e->base_addr + e->length) - down(e->base_addr));
	}

	reserve(0, LOW_MEMORY_END);                                     /* frame 0 (NULL) and the low MiB */
	reserve((uint64_t)(uintptr_t)__kernel_start,
	        (uint64_t)(uintptr_t)__kernel_end - (uint64_t)(uintptr_t)__kernel_start);
	reserve(where, bytes);                                          /* the bitmap marks itself */

	kprintf("[MM] PMM initialized: %u pages total, %u reserved, %u free\n",
	        (unsigned)total_frames, (unsigned)reserved_frames,
	        (unsigned)(total_frames - reserved_frames));
}

void pmm_mark_used(uint64_t phys_start, uint64_t size)
{
	reserve(phys_start, size);
}

void *pmm_alloc_page(void)
{
	for (uint64_t f = 0; f < total_frames; f++) {
		if (!test_bit(f)) {
			set_bit(f);
			used_frames++;
			return (void *)(uintptr_t)(f * PAGE_SIZE);
		}
	}
	return NULL;
}

void *pmm_alloc_contiguous(uint32_t page_count)
{
	if (!page_count)
		return NULL;
	for (uint64_t f = 0; f + page_count <= total_frames; f++) {
		uint32_t n = 0;
		while (n < page_count && !test_bit(f + n))
			n++;
		if (n == page_count) {
			for (uint32_t i = 0; i < page_count; i++)
				set_bit(f + i);
			used_frames += page_count;
			return (void *)(uintptr_t)(f * PAGE_SIZE);
		}
		f += n;                         /* skip the blocked frame */
	}
	return NULL;
}

void pmm_free_page(void *phys_addr)
{
	uint64_t f = (uint64_t)(uintptr_t)phys_addr / PAGE_SIZE;
	if (f >= total_frames)
		panic("pmm_free_page: address beyond RAM", phys_addr);
	/* A frame that is not allocated (a double free, or one never handed out) has its bit clear. */
	if (!test_bit(f))
		panic("pmm_free_page: double free", phys_addr);
	clr_bit(f);
	used_frames--;
}

uint64_t pmm_total_count(void)    { return total_frames; }
uint64_t pmm_reserved_count(void) { return reserved_frames; }
uint64_t pmm_free_count(void)     { return total_frames - reserved_frames - used_frames; }

/* --- DMA: physically contiguous, caller-aligned ---------------------------- */
#define DMA_MAX 256
static struct { void *base; void *aligned; uint32_t pages; } dma_blocks[DMA_MAX];

void *dma_alloc(unsigned long size, unsigned long align)
{
	if (align < 8)
		align = 8;
	if (align & (align - 1))
		return NULL;                    /* not a power of two */

	unsigned long need = size + align;
	uint32_t pages = (uint32_t)((need + PAGE_SIZE - 1) / PAGE_SIZE);
	int slot = -1;
	for (int i = 0; i < DMA_MAX; i++)
		if (!dma_blocks[i].base) { slot = i; break; }
	if (slot < 0)
		return NULL;
	void *run = pmm_alloc_contiguous(pages);
	if (!run)
		return NULL;

	uintptr_t aligned = ((uintptr_t)run + align - 1) & ~(uintptr_t)(align - 1);
	dma_blocks[slot].base = run;
	dma_blocks[slot].aligned = (void *)aligned;
	dma_blocks[slot].pages = pages;
	return (void *)aligned;
}

void dma_free(void *ptr)
{
	if (!ptr)
		return;
	for (int i = 0; i < DMA_MAX; i++) {
		if (dma_blocks[i].base && dma_blocks[i].aligned == ptr) {
			for (uint32_t p = 0; p < dma_blocks[i].pages; p++)
				pmm_free_page((char *)dma_blocks[i].base + (uint64_t)p * PAGE_SIZE);
			dma_blocks[i].base = NULL;
			return;
		}
	}
}

/* --- Slab: size classes carved from PMM frames ------------------------------ */
#define CLASSES 8
static const size_t class_size[CLASSES] = {16, 32, 64, 128, 256, 512, 1024, 2048};

typedef struct node { struct node *next; } node_t;
static node_t *freelist[CLASSES];

/* Every object kmalloc has handed out, so kfree can tell its own pointers from foreign ones and
 * a double free from a free. Open addressing on the pointer; an entry is never removed, only
 * marked dead, so the same slot is found again when the object is reused. cls >= 0 is a slab
 * class; cls < 0 is a run of -cls frames. A full table fails the allocation (NULL), never a
 * silent mistake. */
#define LIVE_SLOTS (1u << 16)
static struct { void *ptr; uint64_t phys; int32_t cls; int32_t live; } live[LIVE_SLOTS];

static uint32_t slot_of(void *p)
{
	uint64_t x = (uint64_t)(uintptr_t)p;
	return (uint32_t)((x >> 4) * 0x9E3779B1u) & (LIVE_SLOTS - 1);
}

static int track(void *p, uint64_t phys, int32_t cls)
{
	uint32_t s = slot_of(p);
	for (uint32_t n = 0; n < LIVE_SLOTS; n++, s = (s + 1) & (LIVE_SLOTS - 1)) {
		if (live[s].ptr == p || !live[s].ptr) {
			live[s].ptr = p; live[s].phys = phys; live[s].cls = cls; live[s].live = 1;
			return 0;
		}
	}
	return -1;
}

static int find(void *p)
{
	uint32_t s = slot_of(p);
	for (uint32_t n = 0; n < LIVE_SLOTS; n++, s = (s + 1) & (LIVE_SLOTS - 1)) {
		if (live[s].ptr == p)
			return (int)s;
		if (!live[s].ptr)
			return -1;
	}
	return -1;
}

void slab_init(void)
{
	kmemset(freelist, 0, sizeof freelist);
	kmemset(live, 0, sizeof live);
}

static int class_for(size_t size)
{
	for (int i = 0; i < CLASSES; i++)
		if (size <= class_size[i])
			return i;
	return -1;
}

void *kmalloc(size_t size)
{
	if (size == 0)
		return NULL;                    /* mm.md: kmalloc(0) is NULL */
	int c = class_for(size);
	if (c < 0) {
		uint32_t pages = (uint32_t)((size + PAGE_SIZE - 1) / PAGE_SIZE);
		void *run = pmm_alloc_contiguous(pages);
		if (!run)
			return NULL;
		void *p = phys_to_virt((uint64_t)(uintptr_t)run);
		if (track(p, (uint64_t)(uintptr_t)run, -(int32_t)pages) < 0) {
			for (uint32_t i = 0; i < pages; i++)
				pmm_free_page((char *)run + (uint64_t)i * PAGE_SIZE);
			return NULL;
		}
		return p;
	}
	if (!freelist[c]) {
		void *phys = pmm_alloc_page();
		if (!phys)
			return NULL;
		uint8_t *page = phys_to_virt((uint64_t)(uintptr_t)phys);
		size_t n = PAGE_SIZE / class_size[c];
		for (size_t i = 0; i < n; i++) {
			node_t *node = (node_t *)(page + i * class_size[c]);
			node->next = freelist[c];
			freelist[c] = node;
		}
	}
	node_t *node = freelist[c];
	if (track(node, 0, c) < 0)
		return NULL;
	freelist[c] = node->next;
	return node;
}

void *kzalloc(size_t size)
{
	void *p = kmalloc(size);
	if (p)
		kmemset(p, 0, size);
	return p;
}

void kfree(void *ptr)
{
	if (!ptr)
		return;                         /* mm.md: kfree(NULL) is legal */
	int s = find(ptr);
	if (s < 0 || !live[s].live)
		panic("kfree: pointer kmalloc never returned, or a double free", ptr);
	live[s].live = 0;
	if (live[s].cls < 0) {                  /* a run of frames: give them back */
		for (int32_t i = 0; i < -live[s].cls; i++)
			pmm_free_page((void *)(uintptr_t)(live[s].phys + (uint64_t)i * PAGE_SIZE));
		return;
	}
	node_t *node = ptr;
	node->next = freelist[live[s].cls];
	freelist[live[s].cls] = node;
}

void slab_dump_stats(void)
{
	for (int c = 0; c < CLASSES; c++) {
		size_t n = 0;
		for (node_t *p = freelist[c]; p; p = p->next)
			n++;
		kprintf("  class %u: %u free\n", (unsigned)class_size[c], (unsigned)n);
	}
}
